// Generates meditation narration for the last 7 languages: es, fr, de, pt,
// pl, sv, sw. Run with:
//   node --env-file=scripts/audio/.env scripts/audio/generate-final.mjs

import { mkdir, writeFile } from 'node:fs/promises'
